{# Breadcrumb: Box nav > ol > li, Link or Text span. Params: items [{label, href, current, disabled}], ariaLabel, class, attrs. #}
{% set lis %}{% for it in items|default([]) %}{% set c = 'text-sm ' ~ (it.current|default(false) ? 'font-medium' : (it.disabled|default(false) ? 'text-muted-foreground' : 'text-primary underline-offset-4 hover:underline')) %}{% set a = it.current|default(false) ? {'aria-current': 'page'} : {} %}{% set inner %}{% if it.href|default('') and not it.disabled|default(false) %}{{ include('ui/link/Link.html.twig', {href: it.href, class: c, attrs: a, children: it.label|default('')|e}, with_context = false)|trim|raw }}{% else %}{{ include('ui/text/Text.html.twig', {tag: 'span', class: c, attrs: a, children: it.label|default('')|e}, with_context = false)|trim|raw }}{% endif %}{% endset %}{{ include('ui/box/Box.html.twig', {tag: 'li', class: 'inline-flex items-center', children: inner}, with_context = false)|trim|raw }}{% endfor %}{% endset %}
{% set ol %}{{ include('ui/box/Box.html.twig', {tag: 'ol', class: 'flex flex-wrap items-center gap-2', children: lis}, with_context = false)|trim|raw }}{% endset %}
{{ include('ui/box/Box.html.twig', {tag: 'nav', class: compose_join(['text-sm', class|default('')]), attrs: {'aria-label': ariaLabel|default('') ?: 'Breadcrumb'}|merge(attrs|default({})), children: ol}, with_context = false)|trim|raw }}
